//! S2 cell sets (region tag 8) and voxel sets (tag 9), checked against golden
//! vectors.
//!
//! `test-vectors/s2-region/vectors.json` is generated by `generate/` with the
//! reference Go S2 library (`github.com/golang/geo`), while the verifier uses its
//! own port in `octet_verify::s2`. Agreement on every vector is a
//! cross-implementation check, not a self-check: point → cell at every level,
//! id validity, hierarchy, the height-bin index, canonical form, the region
//! digest and containment. The v3 preimage vector is checked in `verify.rs`.

use octet_verify::navigate::proof_region::Region;
use octet_verify::navigate::{LocationProof, ProofRegion, S2CellSet, S2Voxel, S2VoxelSet};
use octet_verify::s2;
use octet_verify::verify::{verify, Status, VerifyOptions};
use serde_json::Value;

fn doc() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/test-vectors/s2-region/vectors.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn hex64(v: &Value) -> u64 {
    u64::from_str_radix(v.as_str().unwrap(), 16).unwrap()
}

fn ids(v: &Value) -> Vec<u64> {
    v.as_array().unwrap().iter().map(hex64).collect()
}

/// The exact f64 bit patterns, so edge points survive parsing.
fn point(v: &Value) -> (f64, f64) {
    let bits = v["point_f64_bits_hex"].as_array().unwrap();
    (f64::from_bits(hex64(&bits[0])), f64::from_bits(hex64(&bits[1])))
}

/// The reference's unit vector for the point, as exact bits.
fn xyz(v: &Value) -> (f64, f64, f64) {
    let b = v["xyz_f64_bits_hex"].as_array().unwrap();
    (f64::from_bits(hex64(&b[0])), f64::from_bits(hex64(&b[1])), f64::from_bits(hex64(&b[2])))
}

/// Edge vectors sit on a cell edge or vertex, where an ulp of `sin`/`cos`
/// decides the leaf. They are pinned through the exact xyz path only.
fn edge(v: &Value) -> bool {
    v["edge"].as_bool().unwrap_or(false)
}

fn section<'a>(d: &'a Value, name: &str) -> &'a Vec<Value> {
    let s = d[name].as_array().unwrap_or_else(|| panic!("section {name}"));
    assert!(!s.is_empty(), "section {name} is empty");
    s
}

#[test]
fn constants_match_the_vectors() {
    let d = doc();
    assert_eq!(d["cellset_domain"].as_str().unwrap().as_bytes(), s2::CELL_SET_DOMAIN);
    assert_eq!(d["max_entries"].as_u64().unwrap() as usize, s2::MAX_CELL_SET_ENTRIES);
}

#[test]
fn points_map_to_the_reference_cells_at_every_level() {
    let d = doc();
    for p in section(&d, "points") {
        let name = p["name"].as_str().unwrap();
        let (x, y, z) = xyz(p);
        let leaf = s2::leaf_from_xyz(x, y, z).unwrap();
        assert_eq!(leaf, hex64(&p["leaf_hex"]), "{name}: leaf from the reference xyz");
        if !edge(p) {
            let (lat, lon) = point(p);
            assert_eq!(s2::leaf_from_lat_lng(lat, lon), Some(leaf), "{name}: leaf from lat/lon");
        }
        assert_eq!(s2::token(leaf), p["leaf_token"].as_str().unwrap(), "{name}: token");
        for (l, want) in p["levels_hex"].as_array().unwrap().iter().enumerate() {
            assert_eq!(s2::parent(leaf, l as u32), hex64(want), "{name}: level {l}");
        }
    }
}

#[test]
fn validity_and_level() {
    let d = doc();
    for v in section(&d, "validity") {
        let name = v["name"].as_str().unwrap();
        let id = hex64(&v["id_hex"]);
        assert_eq!(s2::is_valid(id), v["valid"].as_bool().unwrap(), "{name}: valid");
        if let Some(l) = v["level"].as_u64() {
            assert_eq!(s2::level(id) as u64, l, "{name}: level");
        }
    }
}

#[test]
fn hierarchy_and_leaf_ranges() {
    let d = doc();
    for h in section(&d, "hierarchy") {
        let id = hex64(&h["id_hex"]);
        let at = format!("{:016x}", id);
        assert_eq!(s2::level(id) as u64, h["level"].as_u64().unwrap(), "{at}: level");
        assert_eq!(s2::token(id), h["token"].as_str().unwrap(), "{at}: token");
        assert_eq!(s2::range_min(id), hex64(&h["range_min_hex"]), "{at}: range_min");
        assert_eq!(s2::range_max(id), hex64(&h["range_max_hex"]), "{at}: range_max");
        if h["parent_hex"].is_string() {
            assert_eq!(s2::parent(id, s2::level(id) - 1), hex64(&h["parent_hex"]), "{at}: parent");
        }
        if h["children_hex"].is_array() {
            assert_eq!(s2::children(id).to_vec(), ids(&h["children_hex"]), "{at}: children");
        }
    }
}

#[test]
fn height_bin_index() {
    let d = doc();
    for f in section(&d, "f_index") {
        let h = f64::from_bits(hex64(&f["h_f64_bits_hex"]));
        let zoom = f["zoom"].as_u64().unwrap() as u32;
        let want = if f["valid"].as_bool().unwrap() { Some(f["f"].as_i64().unwrap()) } else { None };
        assert_eq!(s2::f_index(h, zoom), want, "h={h} zoom={zoom}");
    }
}

#[test]
fn canonical_form_and_normalisation() {
    let d = doc();
    let cases = section(&d, "canonical");
    assert!(cases.iter().any(|c| c["canonical"].as_bool().unwrap()));
    assert!(cases.iter().any(|c| !c["canonical"].as_bool().unwrap()));
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let input = ids(&c["input_hex"]);
        let canonical = s2::check_canonical(&input);
        assert_eq!(canonical.is_ok(), c["canonical"].as_bool().unwrap(), "{name}: {canonical:?}");
        if c["normalized_hex"].is_array() {
            assert_eq!(s2::normalize(&input), ids(&c["normalized_hex"]), "{name}: normalisation");
        }
    }
}

#[test]
fn cell_set_digests() {
    let d = doc();
    for g in section(&d, "digests") {
        let cells = ids(&g["cells_hex"]);
        assert_eq!(
            hex::encode(s2::cell_set_digest(&cells)),
            g["digest_hex"].as_str().unwrap(),
            "{}",
            g["name"].as_str().unwrap()
        );
    }
}

fn region_contains(cells: &[u64], p: (f64, f64)) -> (Status, String) {
    contains_check(Region::CellSet(S2CellSet { cell_ids: cells.to_vec() }), p, None)
}

/// The `region-contains` check for `region` at point `p` and height `h`.
fn contains_check(region: Region, p: (f64, f64), h: Option<f64>) -> (Status, String) {
    let proof = LocationProof { claimed_region: Some(ProofRegion { region: Some(region) }), ..Default::default() };
    let r = verify(
        &proof,
        &VerifyOptions {
            now_ms: 0,
            max_age_s: 300,
            hardware_pubkey: None,
            hw_key_source: "test",
            expect_region: None,
            expect_region_type: None,
            expect_region_contains: Some(p),
            expect_region_contains_height_m: h,
            session_nonce: None,
            require_session_binding: false,
            require_schema_v2: false,
            require_attestation: false,
            allow_unbound_app_attest: false,
            require_verdict: None,
            validation_window: None,
        },
    );
    let c = r.checks.iter().find(|c| c.name == "region-contains").expect("region-contains check");
    (c.status, c.detail.clone())
}

#[test]
fn containment_matches_the_reference_in_every_build() {
    let d = doc();
    let cases = section(&d, "containment");
    let inside = cases.iter().filter(|c| c["inside"].as_bool().unwrap()).count();
    assert!(inside >= 10 && cases.len() - inside >= 10, "need both inside and outside cases");
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let cells = ids(&c["cells_hex"]);
        let inside = c["inside"].as_bool().unwrap();
        let (x, y, z) = xyz(c);
        assert!(s2::check_canonical(&cells).is_ok(), "{name}: containment sets are canonical");
        assert_eq!(s2::cell_set_contains_leaf(&cells, s2::leaf_from_xyz(x, y, z).unwrap()), inside, "{name}: via xyz");
        if !edge(c) {
            let want = if inside { Status::Pass } else { Status::Fail };
            let (status, detail) = region_contains(&cells, point(c));
            assert_eq!(status, want, "{name}: {detail}");
        }
    }
}

#[test]
fn non_canonical_sets_fail_containment_and_the_cell_set_check() {
    let leaf = s2::leaf_from_lat_lng(51.5074, -0.1278).unwrap();
    let p = s2::parent(leaf, 12);
    let london = (51.5074, -0.1278);
    // The 4 children of a cell must be sent as the cell itself.
    let (s, d) = region_contains(&s2::children(p), london);
    assert_eq!(s, Status::Fail);
    assert!(d.contains("not canonical") && d.contains("merged"), "{d}");
    let (s, d) = region_contains(&[], london);
    assert_eq!(s, Status::Fail);
    assert!(d.contains("empty"), "{d}");
    let (s, d) = region_contains(&[p], (f64::NAN, 0.0));
    assert_eq!(s, Status::Fail);
    assert!(d.contains("invalid point"), "{d}");
    assert_eq!(region_contains(&[p], london).0, Status::Pass);

    // The `cell-set` check runs on every verification, not only containment.
    let check = |cells: Vec<u64>| {
        let proof = LocationProof {
            claimed_region: Some(ProofRegion { region: Some(Region::CellSet(S2CellSet { cell_ids: cells })) }),
            ..Default::default()
        };
        let r = verify(
            &proof,
            &VerifyOptions {
                now_ms: 0,
                max_age_s: 300,
                hardware_pubkey: None,
                hw_key_source: "test",
                expect_region: None,
                expect_region_type: None,
                expect_region_contains: None,
                expect_region_contains_height_m: None,
                session_nonce: None,
                require_session_binding: false,
                require_schema_v2: false,
                require_attestation: false,
                allow_unbound_app_attest: false,
                require_verdict: None,
                validation_window: None,
            },
        );
        r.checks.iter().find(|c| c.name == "cell-set").map(|c| c.status)
    };
    assert_eq!(check(vec![p]), Some(Status::Pass));
    assert_eq!(check(s2::children(p).to_vec()), Some(Status::Fail));
    assert_eq!(check(vec![p, p]), Some(Status::Fail));
    let too_many: Vec<u64> = (0..=s2::MAX_CELL_SET_ENTRIES as u64).map(|k| s2::range_min(p) + 2 * k).collect();
    assert_eq!(check(too_many), Some(Status::Fail));
}

// --- voxel sets (tag 9) ---

fn voxels(v: &Value) -> Vec<S2Voxel> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|e| S2Voxel {
            cell_id: hex64(&e["cell_hex"]),
            f_zoom: e["f_zoom"].as_u64().unwrap() as u32,
            f_min: e["f_min"].as_i64().unwrap(),
            f_max: e["f_max"].as_i64().unwrap(),
        })
        .collect()
}

fn voxel_section<'a>(d: &'a Value, name: &str) -> &'a Vec<Value> {
    section(&d["voxel_set"], name)
}

/// The `voxel-set` check on a proof claiming these entries.
fn voxel_check(vs: Vec<S2Voxel>) -> Option<Status> {
    let proof = LocationProof {
        claimed_region: Some(ProofRegion { region: Some(Region::VoxelSet(S2VoxelSet { voxels: vs })) }),
        ..Default::default()
    };
    let r = verify(
        &proof,
        &VerifyOptions {
            now_ms: 0,
            max_age_s: 300,
            hardware_pubkey: None,
            hw_key_source: "test",
            expect_region: None,
            expect_region_type: None,
            expect_region_contains: None,
            expect_region_contains_height_m: None,
            session_nonce: None,
            require_session_binding: false,
            require_schema_v2: false,
            require_attestation: false,
            allow_unbound_app_attest: false,
            require_verdict: None,
            validation_window: None,
        },
    );
    r.checks.iter().find(|c| c.name == "voxel-set").map(|c| c.status)
}

#[test]
fn voxel_constants_match_the_vectors() {
    let d = &doc()["voxel_set"];
    assert_eq!(d["voxelset_domain"].as_str().unwrap().as_bytes(), s2::VOXEL_SET_DOMAIN);
    assert_eq!(d["max_entries"].as_u64().unwrap() as usize, s2::MAX_CELL_SET_ENTRIES);
    assert_eq!(d["max_f_zoom"].as_u64().unwrap() as u32, s2::MAX_F_ZOOM);
}

/// Canonical form and normalisation agree with the generator's independent
/// algorithm (footprints split with the reference library's own cell-union
/// intersection and difference), and the `voxel-set` check follows.
#[test]
fn voxel_canonical_form_matches_the_reference() {
    let d = doc();
    let cases = voxel_section(&d, "canonical");
    assert!(cases.iter().any(|c| c["canonical"].as_bool().unwrap()));
    assert!(cases.iter().any(|c| !c["canonical"].as_bool().unwrap()));
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let input = voxels(&c["input"]);
        let canonical = c["canonical"].as_bool().unwrap();
        assert_eq!(s2::check_voxel_canonical(&input).is_ok(), canonical, "{name}: {:?}", s2::check_voxel_canonical(&input));
        match c.get("normalized") {
            Some(n) => {
                let n = voxels(n);
                assert_eq!(s2::normalize_voxels(&input).unwrap(), n, "{name}: normalisation");
                assert_eq!(s2::normalize_voxels(&n).unwrap(), n, "{name}: normalisation is idempotent");
                let all_heights = n.iter().all(|v| (s2::voxel_lo(v), s2::voxel_hi(v)) == (-(1 << 32), 1 << 32));
                assert_eq!(s2::check_voxel_canonical(&n).is_ok(), !all_heights, "{name}: the normalisation is canonical");
            }
            None => assert!(s2::normalize_voxels(&input).is_err(), "{name}: invalid input"),
        }
        let want = if canonical { Status::Pass } else { Status::Fail };
        assert_eq!(voxel_check(input), Some(want), "{name}: voxel-set check");
    }
}

#[test]
fn voxel_set_digests() {
    let d = doc();
    for g in voxel_section(&d, "digests") {
        assert_eq!(
            hex::encode(s2::voxel_set_digest(&voxels(&g["entries"]))),
            g["digest_hex"].as_str().unwrap(),
            "{}",
            g["name"].as_str().unwrap()
        );
    }
}

#[test]
fn voxel_containment_matches_the_reference() {
    let d = doc();
    let cases = voxel_section(&d, "containment");
    let inside = cases.iter().filter(|c| c["inside"].as_bool().unwrap()).count();
    assert!(inside >= 5 && cases.len() - inside >= 5, "need both inside and outside cases");
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let vs = voxels(&c["entries"]);
        assert!(s2::check_voxel_canonical(&vs).is_ok(), "{name}: containment sets are canonical");
        let h = c["h_f64_bits_hex"].as_str().map(|b| f64::from_bits(u64::from_str_radix(b, 16).unwrap()));
        let (status, detail) = contains_check(Region::VoxelSet(S2VoxelSet { voxels: vs.clone() }), point(c), h);
        match h {
            None => {
                assert_eq!(status, Status::Fail, "{name}: no height");
                assert!(detail.contains("needs a height"), "{name}: {detail}");
            }
            Some(h) => {
                let inside = c["inside"].as_bool().unwrap();
                let (x, y, z) = xyz(c);
                let leaf = s2::leaf_from_xyz(x, y, z).unwrap();
                assert_eq!(s2::voxel_set_contains(&vs, leaf, h), Some(inside), "{name}: via xyz");
                let want = if inside { Status::Pass } else { Status::Fail };
                assert_eq!(status, want, "{name}: {detail}");
            }
        }
    }
}

#[test]
fn voxel_containment_fails_closed() {
    let leaf = s2::leaf_from_lat_lng(51.5074, -0.1278).unwrap();
    let p = s2::parent(leaf, 12);
    let london = (51.5074, -0.1278);
    let below120 = S2Voxel { cell_id: p, f_zoom: 22, f_min: 0, f_max: 14 };
    let region = |vs: Vec<S2Voxel>| Region::VoxelSet(S2VoxelSet { voxels: vs });
    assert_eq!(contains_check(region(vec![below120]), london, Some(50.0)).0, Status::Pass);
    // Out of the height range, or not a number.
    for h in [f64::NAN, 33_554_432.0, -33_554_432.5] {
        let (s, d) = contains_check(region(vec![below120]), london, Some(h));
        assert_eq!(s, Status::Fail, "{h}");
        assert!(d.contains("outside"), "{d}");
    }
    // Non-canonical: the same interval written at a finer zoom.
    let finer = S2Voxel { f_zoom: 23, f_min: 0, f_max: 29, ..below120 };
    let (s, d) = contains_check(region(vec![finer]), london, Some(50.0));
    assert_eq!(s, Status::Fail);
    assert!(d.contains("coarsest zoom"), "{d}");
    // All heights everywhere is a cell set, not a voxel set.
    let full = S2Voxel { f_zoom: 0, f_min: -1, f_max: 0, ..below120 };
    let (s, d) = contains_check(region(vec![full]), london, Some(50.0));
    assert_eq!(s, Status::Fail);
    assert!(d.contains("tag 8"), "{d}");
    // Over the entry cap.
    let too_many: Vec<S2Voxel> = (0..=s2::MAX_CELL_SET_ENTRIES as i64)
        .map(|k| S2Voxel { f_zoom: 32, f_min: 2 * k, f_max: 2 * k, ..below120 })
        .collect();
    assert_eq!(voxel_check(too_many), Some(Status::Fail));
    // A height is ignored for other region types.
    assert_eq!(contains_check(Region::CellSet(S2CellSet { cell_ids: vec![p] }), london, Some(f64::NAN)).0, Status::Pass);
}
